+-- Reject banned public food text at publish time and when a public row's
+-- name, normalized_name, brand, or serving_unit_label changes.
+-- Does not scan or rewrite existing rows.
+--
+-- search_path is empty on every function below. Names are schema-qualified
+-- (public. or pg_catalog.). publish_saved_food is SECURITY DEFINER, so a
+-- caller-controlled search_path must not apply.
+
+-- pg_catalog.normalize(text, NFKC) needs PostgreSQL 13 or newer.
+-- supabase/config.toml sets major_version = 17.
+-- Halfwidth dakuten (U+FF9E) and handakuten (U+FF9F) are composed before
+-- NFKC so Dart and Postgres agree even when one NFKC implementation does not.
+
+create or replace function public.compose_halfwidth_voiced(p_text text)
+returns text
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v text := pg_catalog.coalesce(p_text, '');
+  v_out text := '';
+  i integer := 1;
+  n integer := pg_catalog.char_length(v);
+  ch text;
+  nxt text;
+  base_at integer;
+  dakuten_base constant text := 'ｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾊﾋﾌﾍﾎ';
+  dakuten_to constant text := 'ガギグゲゴザジズゼゾダヂヅデドバビブベボ';
+  handakuten_base constant text := 'ﾊﾋﾌﾍﾎ';
+  handakuten_to constant text := 'パピプペポ';
+begin
+  while i <= n loop
+    ch := pg_catalog.substr(v, i, 1);
+    if i < n then
+      nxt := pg_catalog.substr(v, i + 1, 1);
+      if nxt = pg_catalog.chr(65438) then
+        base_at := pg_catalog.strpos(dakuten_base, ch);
+        if base_at > 0 then
+          v_out := v_out || pg_catalog.substr(dakuten_to, base_at, 1);
+          i := i + 2;
+          continue;
+        end if;
+      elsif nxt = pg_catalog.chr(65439) then
+        base_at := pg_catalog.strpos(handakuten_base, ch);
+        if base_at > 0 then
+          v_out := v_out || pg_catalog.substr(handakuten_to, base_at, 1);
+          i := i + 2;
+          continue;
+        end if;
+      end if;
+    end if;
+    v_out := v_out || ch;
+    i := i + 1;
+  end loop;
+  return v_out;
+end;
+$$;
+
+create or replace function public.normalize_public_food_name(p_name text)
+returns text
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v text := pg_catalog.normalize(
+    public.compose_halfwidth_voiced(pg_catalog.coalesce(p_name, '')),
+    'NFKC'::pg_catalog.normalization_form
+  );
+  v_out text := '';
+  i integer;
+  ch text;
+  cp integer;
+  hw_from constant text := 'ｦｧｨｩｪｫｬｭｮｯｰｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓﾔﾕﾖﾗﾘﾙﾚﾛﾜﾝ';
+  hw_to constant text := 'をぁぃぅぇぉゃゅょっーあいうえおかきくけこさしすせそたちつてとなにぬねのはひふへほまみむめもやゆよらりるれろわん';
+  hw_at integer;
+  -- Same pair as publicFoodConfusableFrom / publicFoodConfusableTo.
+  fold_from constant text := 'àáâãäåÀÁÂÃÄÅèéêëÈÉÊËìíîïÌÍÎÏòóôõöÒÓÔÕÖùúûüÙÚÛÜýÿÝŸñÑçÇаАеЕоОрРсСуУхХіІјЈѕЅԁԀ013457@$!';
+  fold_to constant text := 'aaaaaaaaaaaaeeeeeeeeiiiiiiiioooooooooouuuuuuuuyyyynnccaaeeooppccyyxxiijjssddoieastasi';
+begin
+  -- Multi-character folds, then the 1:1 confusable map. Separator folding
+  -- is the loop below. Combining marks U+0300–U+036F are dropped there
+  -- and are not turned into spaces. Kana voicing U+3099/U+309A is kept.
+  v := pg_catalog.replace(v, 'ß', 'ss');
+  v := pg_catalog.replace(v, 'æ', 'ae');
+  v := pg_catalog.replace(v, 'Æ', 'ae');
+  v := pg_catalog.replace(v, 'œ', 'oe');
+  v := pg_catalog.replace(v, 'Œ', 'oe');
+  v := pg_catalog.translate(v, fold_from, fold_to);
+
+  for i in 1..pg_catalog.char_length(v) loop
+    ch := pg_catalog.substr(v, i, 1);
+    cp := pg_catalog.ascii(ch);
+
+    if cp between 768 and 879 then
+      continue;
+    end if;
+
+    if cp = 12288 or cp = 32 or cp = 9 or cp = 10 or cp = 13 then
+      if v_out <> '' and pg_catalog.right(v_out, 1) <> ' ' then
+        v_out := v_out || ' ';
+      end if;
+      continue;
+    end if;
+
+    if cp between 65296 and 65305 then
+      cp := 48 + (cp - 65296);
+    elsif cp between 65313 and 65338 then
+      cp := 97 + (cp - 65313);
+    elsif cp between 65345 and 65370 then
+      cp := 97 + (cp - 65345);
+    else
+      hw_at := pg_catalog.strpos(hw_from, ch);
+      if hw_at > 0 then
+        ch := pg_catalog.substr(hw_to, hw_at, 1);
+        cp := pg_catalog.ascii(ch);
+      end if;
+    end if;
+
+    if cp between 12449 and 12531 then
+      cp := cp - 96;
+    end if;
+
+    if cp between 65 and 90 then
+      cp := 97 + (cp - 65);
+    end if;
+
+    if cp between 97 and 122
+       or cp between 48 and 57
+       or cp between 12353 and 12438
+       or cp between 12449 and 12538
+       or cp between 19968 and 40959
+       or cp = 12540 then
+      v_out := v_out || pg_catalog.chr(cp);
+    elsif v_out <> '' and pg_catalog.right(v_out, 1) <> ' ' then
+      v_out := v_out || ' ';
+    end if;
+  end loop;
+
+  return pg_catalog.btrim(v_out);
+end;
+$$;
+
+create or replace function public.public_food_name_char_is_word(p_char text)
+returns boolean
+language sql
+immutable
+set search_path = ''
+as $$
+  select p_char is not null
+     and (
+       pg_catalog.ascii(p_char) between 48 and 57
+       or pg_catalog.ascii(p_char) between 97 and 122
+       or pg_catalog.ascii(p_char) between 12353 and 12438
+       or pg_catalog.ascii(p_char) between 12449 and 12538
+       or pg_catalog.ascii(p_char) between 19968 and 40959
+       or pg_catalog.ascii(p_char) = 12540
+     );
+$$;
+
+create or replace function public.public_food_name_contains_term(
+  p_name text,
+  p_term text
+)
+returns boolean
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v_from integer := 1;
+  v_at integer;
+  v_before text;
+  v_after text;
+begin
+  if p_term is null or p_term = '' or p_name is null or p_name = '' then
+    return false;
+  end if;
+
+  loop
+    v_at := pg_catalog.strpos(pg_catalog.substr(p_name, v_from), p_term);
+    exit when v_at = 0;
+    v_at := v_from + v_at - 1;
+
+    if v_at = 1 then
+      v_before := null;
+    else
+      v_before := pg_catalog.substr(p_name, v_at - 1, 1);
+    end if;
+
+    if v_at + pg_catalog.char_length(p_term) > pg_catalog.char_length(p_name) then
+      v_after := null;
+    else
+      v_after := pg_catalog.substr(p_name, v_at + pg_catalog.char_length(p_term), 1);
+    end if;
+
+    if (v_before is null or not public.public_food_name_char_is_word(v_before))
+       and (v_after is null or not public.public_food_name_char_is_word(v_after)) then
+      return true;
+    end if;
+
+    v_from := v_at + 1;
+  end loop;
+
+  return false;
+end;
+$$;
+
+create or replace function public.public_food_name_strip_phrase(
+  p_name text,
+  p_phrase text
+)
+returns text
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v text := pg_catalog.coalesce(p_name, '');
+  v_from integer := 1;
+  v_at integer;
+  v_before text;
+  v_after text;
+begin
+  if p_phrase is null or p_phrase = '' then
+    return v;
+  end if;
+
+  loop
+    v_at := pg_catalog.strpos(pg_catalog.substr(v, v_from), p_phrase);
+    exit when v_at = 0;
+    v_at := v_from + v_at - 1;
+
+    if v_at = 1 then
+      v_before := null;
+    else
+      v_before := pg_catalog.substr(v, v_at - 1, 1);
+    end if;
+
+    if v_at + pg_catalog.char_length(p_phrase) > pg_catalog.char_length(v) then
+      v_after := null;
+    else
+      v_after := pg_catalog.substr(v, v_at + pg_catalog.char_length(p_phrase), 1);
+    end if;
+
+    if (v_before is null or not public.public_food_name_char_is_word(v_before))
+       and (v_after is null or not public.public_food_name_char_is_word(v_after)) then
+      v := pg_catalog.substr(v, 1, pg_catalog.greatest(v_at - 1, 0))
+        || ' '
+        || pg_catalog.substr(v, v_at + pg_catalog.char_length(p_phrase));
+      v_from := pg_catalog.greatest(v_at, 1);
+    else
+      v_from := v_at + 1;
+    end if;
+  end loop;
+
+  return v;
+end;
+$$;
+
+create or replace function public.public_food_name_term_uses_substring(p_term text)
+returns boolean
+language sql
+immutable
+set search_path = ''
+as $$
+  select not pg_catalog.regexp_like(p_term, '[a-z0-9]')
+     and pg_catalog.char_length(p_term) >= 2
+     and p_term not in (
+       -- PUBLIC_FOOD_BOUNDARY_ONLY
+       'えろ',
+       'くそ',
+       'ふぇら',
+       'まんこ'
+       -- /PUBLIC_FOOD_BOUNDARY_ONLY
+     );
+$$;
+
+create or replace function public.public_food_name_is_banned(p_name text)
+returns boolean
+language plpgsql
+immutable
+set search_path = ''
+as $$
+declare
+  v_spaced text := public.normalize_public_food_name(p_name);
+  v_compact text;
+  v_term text;
+  v_norm text;
+  v_phrase text;
+  v_words text[] := array[
+    -- PUBLIC_FOOD_BANNED_WORDS
+    'fuck',
+    'fucking',
+    'motherfucker',
+    'shit',
+    'bullshit',
+    'asshole',
+    'bitch',
+    'bastard',
+    'cunt',
+    'dick',
+    'cock',
+    'pussy',
+    'whore',
+    'slut',
+    'nigger',
+    'nigga',
+    'faggot',
+    'retard',
+    'rape',
+    'くそ',
+    'くそったれ',
+    'ちくしょう',
+    'ちんこ',
+    'ちんぽ',
+    'まんこ',
+    'うんこ',
+    'きんたま',
+    'ファック',
+    'セックス',
+    'フェラ',
+    '中出し',
+    '死ね',
+    '殺す',
+    'きちがい',
+    '池沼',
+    'エロ',
+    'おまんこ',
+    'フェラチオ',
+    'イラマチオ',
+    'クンニ',
+    'パイズリ',
+    '顔射',
+    'ぶっかけ',
+    'ごっくん',
+    'ザーメン',
+    'オナニー',
+    '潮吹き',
+    '素股',
+    '手コキ',
+    '手マン',
+    '肉便器',
+    'fellatio',
+    'cunnilingus'
+    -- /PUBLIC_FOOD_BANNED_WORDS
+  ];
+  v_phrases text[] := array[
+    -- PUBLIC_FOOD_ALLOWED_PHRASES
+    'cock tail',
+    'rape seed'
+    -- /PUBLIC_FOOD_ALLOWED_PHRASES
+  ];
+begin
+  if v_spaced = '' then
+    return false;
+  end if;
+
+  foreach v_phrase in array v_phrases loop
+    v_spaced := public.public_food_name_strip_phrase(v_spaced, v_phrase);
+  end loop;
+  v_spaced := pg_catalog.btrim(pg_catalog.regexp_replace(v_spaced, ' +', ' ', 'g'));
+  if v_spaced = '' then
+    return false;
+  end if;
+  v_compact := pg_catalog.replace(v_spaced, ' ', '');
+
+  foreach v_term in array v_words loop
+    v_norm := pg_catalog.replace(public.normalize_public_food_name(v_term), ' ', '');
+    if v_norm = '' then
+      continue;
+    end if;
+
+    if public.public_food_name_term_uses_substring(v_norm) then
+      if pg_catalog.strpos(v_compact, v_norm) > 0 then
+        return true;
+      end if;
+    elsif public.public_food_name_contains_term(v_spaced, v_norm)
+       or public.public_food_name_contains_term(v_compact, v_norm) then
+      return true;
+    end if;
+  end loop;
+
+  return false;
+end;
+$$;
